"""In-memory scheduler that tracks tasks and hands them out in urgency order."""

from typing import List, Optional

from models import Task
from priority import is_more_urgent


class TaskScheduler:
    """Holds a pool of tasks and returns the most urgent one on demand."""

    def __init__(self) -> None:
        self._tasks: List[Task] = []

    def add_task(self, task: Task) -> None:
        self._tasks.append(task)

    def ready_tasks(self, now: float) -> List[Task]:
        """Tasks that are eligible to run at the given time."""
        return [t for t in self._tasks if t.next_attempt_at <= now]

    def _select_most_urgent(self, candidates: List[Task]) -> Task:
        best = candidates[0]
        for candidate in candidates[1:]:
            if is_more_urgent(candidate, best):
                best = candidate
        return best

    def pop_next_task(self, now: float) -> Optional[Task]:
        """Remove and return the task that should run next, if any."""
        candidates = self.ready_tasks(now)
        if not candidates:
            return None
        chosen = self._select_most_urgent(candidates)
        self._tasks.remove(chosen)
        return chosen

    def __len__(self) -> int:
        return len(self._tasks)
